\begin{theorem}
$\sqrt{2} \notin \mathbb{Q}$.
\end{theorem}

\begin{proof}
Suppose $\sqrt{2} = \frac{p}{q}$ with $p, q \in \mathbb{Z}$ coprime. Then
\begin{align}
  2q^2 &= p^2,
\end{align}
so $p^2$ is even, hence $p = 2r$ for some $r \in \mathbb{Z}$. Then
\begin{align}
  2q^2 &= 4r^2,
\end{align}
so $q^2 = 2r^2$ is even, contradicting coprimality.
\end{proof}
